def find_next_occurrence(book, sequence, pos):
    """Find the next occurrence of `book` starting from position `pos`"""
    while pos < len(sequence):
        if sequence[pos] == book:
            return pos
        pos += 1
    return float('inf')

n, k = map(int, input().split())
sequence = list(map(int, input().split()))

reading_area = set()
count = 0

for i, book in enumerate(sequence):
    if book in reading_area:
        continue

    # If there's space, add it
    if len(reading_area) < k:
        reading_area.add(book)
        count += 1
    else:
        # Find the book in reading_area with farthest next occurrence
        farthest_index = -1
        farthest_book = -1

        for candidate in reading_area:
            next_pos = find_next_occurrence(candidate, sequence, i + 1)
            if next_pos > farthest_index:
                farthest_index = next_pos
                farthest_book = candidate

        # Remove the farthest book
        reading_area.remove(farthest_book)
        reading_area.add(book)
        count += 1

print(count)
"}

