import sys

def kmp_failure(pattern):
    m = len(pattern)
    fail = [0] * m
    j = 0
    for i in range(1, m):
        while j > 0 and pattern[j] != pattern[i]:
            j = fail[j-1]
        if pattern[j] == pattern[i]:
            j += 1
            fail[i] = j
        else:
            fail[i] = 0
    return fail

def kmp_search(text, pattern, fail):
    n = len(text)
    m = len(pattern)
    j = 0
    occurrences = []
    for i in range(n):
        while j > 0 and text[i] != pattern[j]:
            j = fail[j-1]
        if text[i] == pattern[j]:
            j += 1
            if j == m:
                occurrences.append(i - m + 1)
                j = fail[j-1]
    return occurrences


def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    q = int(data[2])
    s = data[3]
    t = data[4]

    # Find all occurrences of t in s
    if m > n:
        occurrences = []
    else:
        fail = kmp_failure(t)
        occurrences = kmp_search(s, t, fail)

    # Process queries
    output = []
    for i in range(q):
        l = int(data[5 + 2*i])
        r = int(data[5 + 2*i + 1])

        if m > r - l + 1:
            output.append("0")
            continue

        # Count occurrences in [l, r - m + 1] (convert to 0-indexed)
        count = 0
        for pos in occurrences:
            if pos >= l - 1 and pos <= r - m:
                count += 1
        output.append(str(count))

    print("\n".join(output))

if __name__ == "__main__":
    main()
"}

