def is_valid(s):
    if not s:
        return False

    # If all are H, it's valid
    if all(c == 'H' for c in s):
        return True

    # If the string ends with Q, it's invalid
    if s[-1] == 'Q':
        return False

    # Check if there are equal numbers of H and Q
    # or if there's more H than Q
    if s.count('H') != s.count('Q'):
        if s.count('H') < s.count('Q'):
            return False
    else:
        # If equal, the string should end with H
        if s[-1] != 'H':
            return False

    # Find the block length
    block_len = len(s) // s.count('H') if s.count('H') else len(s)

    # Check if all characters at positions that should be H are H
    for i in range(len(s)):
        if i % block_len == 0:
            if s[i] != 'H':
                return False

    return True

