def min_changes(t, u):
    """Compute the minimum number of changes to transform t into u"""
    n = len(t)
    m = len(u)

    # Case 1: t and u have the same length
    if n == m:
        # Count mismatches
        return sum(1 for i in range(n) if t[i] != u[i])

    # Case 2: t is shorter than u
    if n < m:
        # We need to add (m - n) characters
        # We can also consider the best alignment of t with u
        # Align t with prefix of u up to length n
        max_match = 0
        for i in range(min(n, m)):
            if t[i] == u[i]:
                max_match += 1
        # Add the number of characters we need to add
        return (m - n) + (n - max_match)

    # Case 3: t is longer than u
    if n > m:
        # We need to delete (n - m) characters
        # Align prefix of t with u up to length m
        max_match = 0
        for i in range(min(n, m)):
            if t[i] == u[i]:
                max_match += 1
        # Delete the number of characters we need to delete
        return (n - m) + (m - max_match)

# Read input
