    strings = [sys.stdin.readline().strip() for _ in range(n)]

    # Calculate weight for each letter
    weight = {}
    for s in strings:
        length = len(s)
        for i, c in enumerate(s):
            power = 10 ** (length - i - 1)
            weight[c] = weight.get(c, 0) + power

    # Sort letters by descending weight
    sorted_letters = sorted(weight.keys(), key=lambda c: -weight[c])

    # Assign digits 0-9 to letters
    digit_map = {}
    for i, c in enumerate(sorted_letters):
        digit_map[c] = i

    # Calculate the minimum sum
    total = 0
    for s in strings:
        num = 0
        for c in s:
            num = num * 10 + digit_map[c]
        total += num

    print(total)

if __name__ == "__main__":
    solve()
