import sys

def solve():
    MOD = 998244353
    n, k = map(int, sys.stdin.readline().split())
    lamps = []
    for _ in range(n):
        l, r = map(int, sys.stdin.readline().split())
        lamps.append((l, r))

    # Sort by start time
    lamps.sort()

    # Precompute factorials and inverse factorials for combinations
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    inv_fact = [1] * (n + 1)
    inv_fact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n - 1, -1, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD

    def comb(n, k):
        if n < k or k < 0:
            return 0
        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

    ans = 0

    # For each lamp i as the last in a valid set
    for i in range(n):
        # Find how many lamps before i have end time >= l_i
        count = 0
        for j in range(i):
            if lamps[j][1] >= lamps[i][0]:
                count += 1
            else:
                break

        # Number of ways to choose k-1 lamps from these count lamps
        ans = (ans + comb(count, k - 1)) % MOD

    print(ans)

if __name__ == "__main__":
    solve()
"}

