def get_component_info(root):
    nodes = 0
    edges = 0

    # Use DFS to count nodes in this component
    stack = [root]
    visited[root] = True

    while stack:
        node = stack.pop()
        nodes += 1

        for neighbor in adj[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                stack.append(neighbor)

    # Count edges by checking for each edge if both are visited
    for x, y in adj.items():
        if visited[x]:
            for y2 in y:
                if visited[y2]:
                    edges += 1

    return nodes, edges

