# If there are ties, we remove the leftmost one.

# Let's simulate using a segment tree approach
from collections import defaultdict

class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.tree = []
        self.data = data
        self.tree.append(None)
        self.left = [0] * (4 * self.n)
        self.right = [0] * (4 * self.n)
        self.value = [0] * (4 * self.n)
        self.max_len = [0] * (4 * self.n)
        self.build(1, 0, self.n - 1)

    def build(self, node, l, r):
        if l == r:
            self.left[node] = l
            self.right[node] = r
            self.value[node] = self.data[l]
            self.max_len[node] = 1
            return

        mid = (l + r) // 2
        self.build(2 * node, l, mid)
        self.build(2 * node + 1, mid + 1, r)

        self.left[node] = self.left[2 * node]
        self.right[node] = self.right[2 * node + 1]
        self.value[node] = self.value[2 * node]
        self.max_len[node] = max(self.max_len[2 * node], self.max_len[2 * node + 1])

    def query_max(self, node, l, r):
        if r < self.left[node] or l > self.right[node]:
            return (0, -1, -1)

        if l <= self.left[node] and self.right[node] <= r:
            return (self.max_len[node], self.left[node], self.right[node])

        mid = (self.left[node] + self.right[node]) // 2
        left_max, left_l, left_r = self.query_max(2 * node, l, mid)
        right_max, right_l, right_r = self.query_max(2 * node + 1, mid + 1, r)

        if left_max > right_max:
            return (left_max, left_l, left_r)
        elif right_max > left_max:
            return (right_max, right_l, right_r)
        else:
            # Tie, return the leftmost segment
            return (left_max, left_l, left_r)

    def remove_segment(self, l, r):
        def remove(node, seg_l, seg_r):
            if seg_r < l or seg_l > r:
                return (seg_l, seg_r)

            if l <= seg_l and seg_r <= r:
                # This segment is entirely removed
                left_l, left_r = remove(2 * node, self.left[node], self.right[node])
                right_l, right_r = remove(2 * node + 1, self.left[node], self.right[node])
                return (left_l, right_r)

            mid = (seg_l + seg_r) // 2
            left_l, left_r = remove(2 * node, seg_l, mid)
            right_l, right_r = remove(2 * node + 1, mid + 1, seg_r)

            # Update left and right boundaries
            self.left[node] = left_l
            self.right[node] = right_r

            # Calculate new max length
            self.max_len[node] = max(self.max_len[2 * node], self.max_len[2 * node + 1])

            # If left and right parts have the same value, they merge
            if left_l != -1 and right_l != -1 and self.value[2 * node] == self.value[2 * node + 1]:
                self.value[node] = self.value[2 * node]
                self.max_len[node] = self.max_len[2 * node] + self.max_len[2 * node + 1]
            elif left_l != -1:
