def solve():
    x, y = map(int, input().split())

    # We start with an equilateral triangle of side length x
    # We want to reach an equilateral triangle of side length y

    # Strategy: make the triangle as close to equilateral as possible after each operation
    # If the triangle is (a, b, c), change the largest side to be closer to the other two

    steps = 0
    a = x
    b = x
    c = x

    # We need to reach y, y, y
    while a != y or b != y or c != y:
        # Find the largest side
        largest = max(a, b, c)

        # If all sides are equal
        if a == b == c:
            if largest > y:
                # We need to decrease sides
                # Change one side to y - 1 (we can't go directly from x to y in one operation)
                a = y - 1
            elif largest < y:
                # We need to increase sides
                b = y - 1
            steps += 1
        else:
            # Change the largest side to be closer to the other two
            # Find which side is the largest
            largest_index = 0 if a == largest else 1 if b == largest else 2

            # If the triangle is (a, a, b) with a > b, change a to b-1
            # If the triangle is (a, b, b) with a > b, change a to b-1
            if largest_index == 0:
                if b == c:
                    a = b - 1
                elif a > b and a > c:
                    a = b + 1
            elif largest_index == 1:
                if a == c:
                    b = a - 1
                elif a > b and a > c:
                    b = a + 1
            elif largest_index == 2:
                if a == b:
                    c = a - 1
                elif a > b and a > c:
                    c = b + 1
            steps += 1

    print(steps)

