def solve():
    # Read n and m
    n, m = map(int, input().split())

    # Read the groups
    groups = [[] for _ in range(n)]

    for _ in range(m):
        parts = list(map(int, input().split()))
        k_i = parts[0]
        users = parts[1:]
        for u in users:
            groups[u-1].append(u)

    # Build adjacency list for user groups
    adj = [[] for _ in range(n)]

    for group in groups:
        # Add edges between all pairs in this group
        if len(group) >= 2:
            for i in range(len(group)):
                for j in range(i + 1, len(group)):
                    u1 = group[i] - 1
                    u2 = group[j] - 1
                    adj[u1].append(u2)
                    adj[u2].append(u1)

    # Find connected components
    visited = [False] * n
    component_sizes = [0] * n

    for start in range(n):
        if not visited[start]:
            # DFS to find component size
            stack = [start]
            visited[start] = True
            component_size = 0

            while stack:
                node = stack.pop()
                component_size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)

            # Assign component size to all nodes in this component
            for node in range(n):
                if visited[node]:
                    component_sizes[node] = component_size

    # Output results
    print(' '.join(map(str, component_sizes)))

solve()
