import sys

def longest_non_decreasing_subsequence(n, T, a):
    # Create the full array by repeating a T times
    full_array = a * T

    # Initialize dp array
    dp = [1] * len(full_array)  # Each element can be a subsequence of length 1

    # Fill dp array
    for i in range(len(full_array)):
        for j in range(i):
            if full_array[j] <= full_array[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Read input
    n = int(data[0])
    T = int(data[1])
    a = list(map(int, data[2:2+n]))

    # Solve the problem
    result = longest_non_decreasing_subsequence(n, T, a)

    # Print the result
    print(result)

if __name__ == "__main__":
    main()
