from collections import defaultdict, deque
import sys


def solve():
    n, m = map(int, sys.stdin.readline().split())

    # Build adjacency list
    graph = defaultdict(list)
    for _ in range(m):
        parts = list(map(int, sys.stdin.readline().split()))
        k = parts[0]
        if k == 0:
            continue
        users = parts[1:]
        # Add edges between all pairs in this group
        for i in range(len(users)):
            for j in range(i + 1, len(users)):
                u = users[i]
                v = users[j]
                graph[u].append(v)
                graph[v].append(u)

    # Find connected components
    visited = [False] * (n + 1)  # users are 1-indexed
    result = [0] * (n + 1)

    for user in range(1, n + 1):
        if not visited[user]:
            # BFS to find component size
            q = deque([user])
            visited[user] = True
            count = 0
            while q:
                node = q.popleft()
                count += 1
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        q.append(neighbor)
            # All users in this component should have the same count
            for i in range(1, n + 1):
                if visited[i]:
                    result[i] = count

    # Print results
    print(' '.join(str(result[i]) for i in range(1, n + 1)))

if __name__ == '__main__':
    solve()
