# For each element, we need to check if we can move it to its correct position
# We can only move within blocks of consecutive allowed swaps

for i in range(n):
    # The element at position i should be i+1
    correct = i + 1

    if a[i] == correct:
        continue

    # Find where the correct element is
    pos = a.index(correct, i)

    # Check if we can move from pos to i using allowed swaps
    # We need a continuous block of allowed swaps from pos to i

    # Check if we can move left
    can_move_left = True
    for j in range(pos, i, -1):
        if s[j-1] != '1':
            can_move_left = False
            break

    # Check if we can move right
    can_move_right = True
    for j in range(i, pos):
        if s[j] != '1':
            can_move_right = False
            break

    if can_move_left:
        # Move left
        for j in range(pos, i, -1):
            a[j-1], a[j] = a[j], a[j-1]
    elif can_move_right:
        # Move right
        for j in range(i, pos):
            a[j], a[j+1] = a[j+1], a[j]
    else:
        print("NO")
        exit()

print("YES")
