    # We need to count the number of trees (connected components where edges = nodes - 1)
    # That means we need to find connected components with no cycles (trees)

    # Let's find the number of connected components with exactly (nodes - edges) = 1
    # That means edges = nodes - 1, which is a tree

    # We can use Union-Find (Disjoint Set Union) to find connected components
    parent = list(range(n + 1))  # 1-indexed
    rank = [1] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])  # Path compression
        return parent[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            if rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            elif rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            else:
                parent[root_y] = root_x
                rank[root_x] += 1

    # Find connected components
    component_size = {}  # {root: size}
    for i in range(1, n + 1):
        if find(i) == i:
            component_size[i] = 1

    # Find edges
    edges = [[] for _ in range(n + 1)]
    for _ in range(m):
