import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    parent = list(range(n + 1))  # 1-indexed
    size = [1] * (n + 1)

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return
        if size[u_root] < size[v_root]:
            u_root, v_root = v_root, u_root
        parent[v_root] = u_root
        size[u_root] += size[v_root]

    for _ in range(m):
        k = int(next(it))
        if k < 2:
            # Not enough users to form edges
            for _ in range(k):
                next(it)
            continue
        # Union all consecutive pairs
        users = [int(next(it)) for _ in range(k)]
        for i in range(k - 1):
            union(users[i], users[i + 1])

    # Output results
    results = [str(size[find(i)]) for i in range(1, n + 1)]
    sys.stdout.write(" ".join(results))

if __name__ == "__main__":
    main()
"}

