def can_sort_with_one_swap(row):
    mismatch = []
    for i, val in enumerate(row, 1):
        if val != i:
            mismatch.append(i)

    if len(mismatch) == 0:
        return True
    if len(mismatch) == 2:
        i, j = mismatch
        temp = row[:]
        temp[i-1], temp[j-1] = temp[j-1], temp[i-1]
        return temp == list(range(1, len(row)+1))
    return False

