    print("YES")
    exit()

# Try all possible column swaps (col1, col2) where col1 < col2
for col1 in range(m):
    for col2 in range(col1 + 1, m):
        # Create a copy of the table with columns swapped
        swapped_table = [row[:] for row in table]
        for row in swapped_table:
            row[col1], row[col2] = row[col2], row[col1]

        all_sorted = True
        for row in swapped_table:
            if not can_sort_with_one_swap(row):
                all_sorted = False
                break

        if all_sorted:
            print("YES")
            exit()

