    if k <= b:
        # Cannot play and charge, need at least a charge for just play
        if k <= a:
            print(-1)
        else:
            # Can just play, but we need to ensure charge never drops below 0
            # If we just play once, charge becomes k - a, which needs to be > 0
            if k - a <= 0:
                print(-1)
            else:
                # After one just play, we need to charge n-1 times
                # Each charge uses b, so total charge used after n turns = a + (n-1)*b
                if k > a + (n-1)*b:
                    # We can just play at least once
                    print(1)
                else:
                    # We need to check if we can complete all turns
                    # Charge after n turns = k - a - (n-1)*b
                    # Need this > 0
                    if k - a - (n-1)*b > 0:
                        print(1)
                    else:
                        print(-1)
    else:
        # Can play and charge, but we want to maximize just play
        if k <= a:
            # Cannot just play, must play and charge all n times
            # Charge after n turns = k - n*b
            if k > n*b:
                print(0)
            else:
                print(-1)
        else:
            # Can just play, let's try to maximize
            # Maximum just play turns = floor((k - n*b - 1) / (a - b))
            # But we also need to ensure charge > 0 at each step
            if k > n*b:
                x = (k - n*b - 1) // (a - b)
                print(x if x >= 0 else -1)
            else:
                print(-1)
