import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    table = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(m)]
        table.append(row)
    expected = list(range(1, m + 1))

    def check_col_perm(col_perm: tuple) -> bool:
        # col_perm: list of column indices, len m
        # for each row, check if it can be sorted with at most one swap
        for row in table:
            new_row = [row[col] for col in col_perm]
            # count mismatches
            mismatches = []
            for i in range(m):
                if new_row[i] != expected[i]:
                    mismatches.append(i)
            if len(mismatches) == 0:
                continue
            elif len(mismatches) == 2:
                i, j = mismatches
                if new_row[i] == expected[j] and new_row[j] == expected[i]:
                    continue
                else:
                    return False
            else:
                return False
        return True

    # identity
    if check_col_perm(tuple(range(m))):
        print("YES")
        return

    # try all transpositions of two columns
    for i in range(m):
        for j in range(i + 1, m):
            col_perm = list(range(m))
            col_perm[i], col_perm[j] = col_perm[j], col_perm[i]
            col_perm = tuple(col_perm)
            if check_col_perm(col_perm):
                print("YES")
                return

    print("NO")

if __name__ == "__main__":
