    # Find segments where we can sort
    # If we cannot swap at position i, we need a[i] == sorted_a[i]
    for i in range(n - 1):
        if allowed_swaps[i] == '0':
            # Cannot swap at position i (1-indexed), so a[i] must be sorted
            if a[i] != sorted_a[i]:
                return "NO"

    # Also check the last position (n)
    if a[n - 1] != sorted_a[n - 1]:
        return "NO"

