import sys

def is_in_check(king_pos, rook_pos, board):
    """Check if king is in check by a rook"""
    # Convert to coordinates
    def pos_to_int(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    king_x, king_y = pos_to_int(king_pos)
    rook_x, rook_y = pos_to_int(rook_pos)

    # Check if rook is in same row or column
    if rook_x != king_x and rook_y != king_y:
        return False

    # Check if there's a clear line of sight
    if rook_x == king_x:
        # Same row, check between columns
        min_col = min(rook_y, king_y)
        max_col = max(rook_y, king_y)
        for col in range(min_col + 1, max_col):
            if board[king_x][col] is not None:
                return False
    else:
        # Same column, check between rows
        min_row = min(rook_x, king_y)
        max_row = max(rook_x, king_y)
        for row in range(min_row + 1, max_row):
            if board[row][king_y] is not None:
                return False

    return True

def is_square_safe(pos, rook_positions, king_pos, board):
    """Check if a square is safe for the black king"""
