    for l in range(len_u + 1, len_s + 1):
        for start in range(len_s - l + 1):
            # Try all possible substrings of length len_u within this longer substring
            for i in range(l - len_u + 1):
                # Compare substring from start+i of length len_u with u
                matches = 0
                for j in range(len_u):
                    if s[start+i+j] == u[j]:
                        matches += 1
                cost = (l - len_u) + (len_u - matches)
