def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    colors = list(map(int, data[2:2+n]))

    # Count frequency of each color
    freq = {}
    for c in colors:
        freq[c] = freq.get(c, 0) + 1

    # We want to maximize distinct pairs, so we try to pair with different colors first
    pairs = []

    # For each color, try to pair with different colors first
    for c1 in freq:
        count = freq[c1]

        # Try to pair with other colors
        for c2 in freq:
            if c1 == c2:
                continue

            if freq[c2] > 0:
                for _ in range(min(count, freq[c2])):
                    pairs.append((c1, c2))
                    freq[c1] -= 1
                    freq[c2] -= 1

        # Pair remaining with itself
        if freq[c1] > 0:
            for _ in range(freq[c1]):
                pairs.append((c1, c1))
                freq[c1] -= 1

    # We need exactly n pairs, so we just take the first n pairs
    print(len(pairs[:n]))
    for pair in pairs[:n]:
        print(pair[0], pair[1])

