from collections import defaultdict

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    a = int(next(it))
    n = int(next(it))
    m = int(next(it))

    rain_segments = []
    for _ in range(n):
        l = int(next(it))
        r = int(next(it))
        rain_segments.append((l, r))

    umbrellas = []
    for _ in range(m):
        x = int(next(it))
        p = int(next(it))
        umbrellas.append((x, p))

    # Sort rain segments by start
    rain_segments.sort()

    # Find positions with umbrellas
    pos_to_umbrellas = defaultdict(list)
    for x, p in umbrellas:
        pos_to_umbrellas[x].append(p)

    # DP: dp[pos] = {frozenset: min_fatigue}
    dp = defaultdict(lambda: defaultdict(lambda: float('inf')))
    dp[0][frozenset()] = 0  # Start at position 0 with no umbrellas and 0 fatigue

    for pos in range(a + 1):
        # Create a copy of current state
        current_states = list(dp[pos].items())

        for umb_set, fatigue in current_states:
            # Move to next position
            next_pos = pos + 1
            if next_pos <= a:
                # Determine if we need umbrellas for this movement
                need_umbrella = False
                for l, r in rain_segments:
                    if l <= pos and r > pos and l > pos - 1:
                        # [pos, pos+1] is a rain segment
                        need_umbrella = True
                        break

                if need_umbrella and len(umb_set) > 0:
                    fatigue_next = fatigue + sum(umb_set)
                    if fatigue_next < dp[next_pos][umb_set]:
                        dp[next_pos][umb_set] = fatigue_next
                elif not need_umbrella:
                    fatigue_next = fatigue + sum(umb_set)
                    if fatigue_next < dp[next_pos][umb_set]:
                        dp[next_pos][umb_set] = fatigue_next

            # Pick up umbrellas at this position
            if pos in pos_to_umbrellas:
                for p in pos_to_umbrellas[pos]:
                    new_umb_set = set(umb_set)
                    new_umb_set.add(p)
                    new_umb_set = frozenset(new_umb_set)
                    if fatigue < dp[pos][new_umb_set]:
                        dp[pos][new_umb_set] = fatigue

    if a in dp and dp[a]:
        print(min(dp[a].values()))
    else:
        print(-1)

if __name__ == "__main__":
    solve()
