def solve():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        table = []
        for _ in range(n):
            table.append(list(input().strip()))

        operations = []

        # Process from top-left to bottom-right
        for i in range(n):
            for j in range(m):
                # Skip bottom-right cell for now
                if i == n - 1 and j == m - 1:
                    continue
                # If the cell is 1, flip it along with two others
                if table[i][j] == '1':
                    # Choose operation: flip (i, j), (i+1, j), (i+1, j+1) and leave (i, j+1)
                    # This works if we're not at the bottom row
                    if i < n - 1:
                        operations.append((i + 1, j + 1, i + 1, j + 2, i + 2, j + 1))
                        for x in range(i, i + 2):
                            for y in range(j, j + 2):
                                if (x, y) != (i + 1, j + 1):  # leave (i+1, j+1) untouched
                                    table[x][y] = '1' if table[x][y] == '0' else '0'
                    else:
                        # Bottom row, can't go down
                        # Need to flip using operation that covers this row
                        operations.append((n, m, n, 1, 1, m))
                        for x in range(n, n + 1):  # only the bottom-right cell
                            for y in range(m, m + 1):
                                table[x][y] = '1' if table[x][y] == '0' else '0'

        # Handle bottom-right cell
        if table[n-1][m-1] == '1':
            operations.append((n, m, n, 1, 1, m))
            for x in range(n, n + 1):
                for y in range(m, m + 1):
                    table[x][y] = '1' if table[x][y] == '0' else '0'

        # Now check if any cells are still 1
        for row in table:
            if '1' in row:
                print("Problem! There are still 1s left.")
                exit()

        print(len(operations))
        for op in operations:
            print("{} {} {} {} {} {}".format(*op))

