        if grid[i][j] == 'X':
            x_positions.append((i, j))

# For the rectangle to be solid, every cell must be either on the border or covered by an 'X'
# From the two pieces, we get at most 2n * 2m cells, but many will be the same

# Let's think about the minimum bounding rectangle
# The border of the rectangle consists of all cells that are on the edge of the rectangle
# If we place two pieces, we get at most 2n * m cells (if we double width) or n * 2m cells (if we double height)

# For the rectangle to be solid:
# - We need enough 'X's to cover the interior cells (not on the border)
# - The 'X's must be positioned such that they cover the necessary cells

# The number of interior cells (not on the border) in a rectangle of size w x h:
# interior = (w - 2) * (h - 2)
# The number of cells that must be covered by 'X's = interior

# Case 1: Try to form a rectangle of size n x 2m (doubling width)
# The width becomes 2m, height remains n
# The interior size = (2m - 2) * (n - 2)
# We need at least this many 'X's
# And we need to check if we can position the two pieces such that they cover the rectangle

def can_form_rectangle(w, h):
    # Check if we have enough 'X's to cover the interior
    # Each piece has n * m cells, but we only use some of them
    # The number of 'X's we have = len(x_positions)
    interior = (w - 2) * (h - 2)
    if interior > len(x_positions):
        return False

    # Try all possible positions for the first piece
    for i1 in range(n):
        for j1 in range(m):
            if grid[i1][j1] != 'X':
                continue

            # Place the second piece such that we cover the rectangle
            # The second piece must be placed somewhere
            found = False
            for i2 in range(n):
                for j2 in range(m):
                    if i1 == i2 and j1 == j2:
                        continue  # No overlap
                    if grid[i2][j2] != 'X':
                        continue

                    # Check if the union of the two pieces covers the rectangle
                    covered = set()
                    for (x1, y1) in x_positions:
                        if i1 <= x1 < i1 + n and j1 <= y1 < j1 + m:
                            covered.add((x1, y1))
                    for (x2, y2) in x_positions:
                        if i2 <= x2 < i2 + n and j2 <= y2 < j2 + m:
                            covered.add((x2, y2))

                    # Check if all interior cells are covered
                    all_covered = True
                    for i in range(1, w - 1):
                        for j in range(1, h - 1):
                            if (i, j) not in covered:
