# Solve Jumping Ball problem
n = int(input())
string = input()

# For each position, check if it eventually leads to an out-of-bounds position
fall_count = 0

for start in range(1, n + 1):
    i = start
    fell = False

    while 1 <= i <= n:
        # Check if we fall from this position
        if i == 1 and string[0] == '<':
            fell = True
            break
        if i == n and string[-1] == '>':
            fell = True
            break

        # Move to the next position
        if string[i - 1] == '<':
            i -= 1
        else:
            i += 1

    if fell:
        fall_count += 1

print(fall_count)
"}

