    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:n+1]))
    b = list(map(int, data[n+1:2*n+1]))

    always_zero = 0
    counts = {}

    for ai, bi in zip(a, b):
        if ai == 0:
            if bi == 0:
                always_zero += 1
        else:
            key = -bi / ai
