import sys
from math import ceil

def solve():
    n = int(sys.stdin.readline())
    cards = []

    for _ in range(n):
        f, b = map(int, sys.stdin.readline().split())
        cards.append((f, b))

    # Count front and back colors
    front_count = {}
    back_count = {}

    for f, b in cards:
        front_count[f] = front_count.get(f, 0) + 1
        back_count[b] = back_count.get(b, 0) + 1

    target = ceil(n / 2)
    min_flips = float('inf')

    # Check each possible color (both front and back)
    all_colors = set(front_count.keys()).union(set(back_count.keys()))

    for color in all_colors:
        front = front_count.get(color, 0)
        back = back_count.get(color, 0)

        # To get at least 'target' cards showing 'color':
        # - If front >= target: 0 flips
        # - Otherwise: need to flip at least (target - front) cards from back
        # But we need to have enough back cards
        if front >= target:
            min_flips = min(min_flips, 0)
        elif front + back >= target:
            needed = target - front
            min_flips = min(min_flips, needed)

    if min_flips != float('inf'):
        print(min_flips)
    else:
        print(-1)

if __name__ == "__main__":
    solve()

