n, x = map(int, input().split())
lights_intervals = []

for _ in range(n):
    l, r = map(int, input().split())
    lights_intervals.append((l, r))

# We need to track current position and calculate minimum total cost
# This is a classic dynamic programming problem

# Instead of tracking all positions, we only track the boundaries of intervals
# and the positions from the previous turn

# We'll use a set to track positions we need to consider at each step
# Positions to consider: l_i - 1, l_i, r_i, r_i + 1, and previous positions

positions = {x: 0}

for i in range(n):
    l, r = lights_intervals[i]
    next_l, next_r = lights_intervals[i+1] if i+1 < n else (l, r)

    # Calculate distances to closest light in next interval
    distances = {}
    for pos in positions:
        if next_l <= pos <= next_r:
            distances[pos] = 0
        elif pos > next_r:
            distances[pos] = pos - next_r
        else:
            distances[pos] = next_l - pos

    # Create new positions dictionary
    new_positions = {}

    # Option 1: stay at same position
    for prev_pos in positions:
        for pos in positions:
            move_cost = abs(pos - prev_pos)
            cost = positions[prev_pos] + move_cost + distances[pos]
            if pos in new_positions:
                new_positions[pos] = min(new_positions[pos], cost)
            else:
                new_positions[pos] = cost

    # Option 2: move to endpoints of current interval
    for prev_pos in positions:
        move_cost = abs(l - prev_pos)
        cost = positions[prev_pos] + move_cost + distances[l]
        if l in new_positions:
            new_positions[l] = min(new_positions[l], cost)
        else:
            new_positions[l] = cost

        move_cost = abs(r - prev_pos)
        cost = positions[prev_pos] + move_cost + distances[r]
        if r in new_positions:
            new_positions[r] = min(new_positions[r], cost)
        else:
            new_positions[r] = cost

    # Option 3: move to any light in current interval
    for prev_pos in positions:
        for light in range(l, r + 1):
            move_cost = abs(light - prev_pos)
            cost = positions[prev_pos] + move_cost + distances[light]
            if light in new_positions:
                new_positions[light] = min(new_positions[light], cost)
            else:
                new_positions[light] = cost

    positions = new_positions

print(min(positions.values()))
