def max_ones_number(l, r):
    if r == 0:
        return 0

    # Find the position of the highest set bit
    highest_bit = r.bit_length() - 1

    # Fill all lower bits with 1
    number = (1 << highest_bit) - 1

    if number >= l:
        return number

    # If not in range, try the next lower bit
    return number ^ (1 << highest_bit)

