import sys

def count_numbers_with_digit_sum(total_sum, max_digits):
    """Count numbers with up to max_digits digits and digit sum equal to total_sum"""
    # Use stars and bars with constraints
    # First digit >= 1, others >= 0
    # Sum of digits = total_sum
    # Count combinations with constraints
    if total_sum < 1:
        return 0

    # Count ways to distribute remaining total_sum-1 among max_digits positions
    # Using stars and bars: C(n + k - 1, k - 1)
    return 1 + sum(1 for k in range(2, max_digits + 1)
                   for ways in range(1, total_sum - k + 1) for _ in range(ways))


def find_kth_perfect(k):
    """Find the k-th smallest perfect number"""
    # Find the number of digits in the answer
    for num_digits in range(1, 20):
        # For each possible digit count, find how many numbers have that digit count
        # and sum of digits = 10
        count = count_numbers_with_digit_sum(10, num_digits)
        if count >= k:
            # Now find the k-th number with num_digits digits and digit sum = 10
            # Generate numbers in increasing order
            n = 10**(num_digits - 1)
            found = 0
            while True:
                if sum(int(d) for d in str(n)) == 10:
                    found += 1
                    if found == k:
                        return n
                n += 1
    return -1

k = int(sys.stdin.readline())
print(find_kth_perfect(k))
