import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    results = []

    for _ in range(t):
        a = int(data[idx]); idx += 1
        b = int(data[idx]); idx += 1
        c = int(data[idx]); idx += 1

        sum_abc = a + b + c + 1
        if sum_abc % 9 != 0:
            results.append("NO")
            continue

        k = sum_abc // 9
        if a >= k and b >= k and c >= k:
            results.append("YES")
        else:
            results.append("NO")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

