    """
    Process a cd command with the given path.
    - current_path: list representing the current directory (e.g., ["home", "vasya"])
    - path: string representing the path to change to
    - Returns: new current directory path
    """
    if path[0] == '/':
        # Absolute path: start from root
        new_path = []
    else:
        # Relative path: start from current directory
        new_path = list(current_path)

    # Split the path by '/'
    components = path.split('/')

    for comp in components:
        if comp == '..':
            # Move up one level
            if new_path:
                new_path.pop()
        elif comp:
            # Add the component to the path
            new_path.append(comp)

    return new_path

def pwd(current_path):
    """
    Print the pwd output for the given current directory.
    """
    print('/' + '/'.join(current_path) + '/')

